const indeterminateFor = <Operation>(
  command: ProductCommercialFeeBulkCommand<Operation>,
  error: ProductCommercialFeeBulkPortFailure,
  resolvedBy: ProductCommercialFeeBulkTargetOutcome['resolvedBy'],
): ProductCommercialFeeBulkTargetOutcome =>
  outcomeFor(command, { outcome: 'INDETERMINATE', reasonCode: error._tag }, resolvedBy);

const ownerOutcomeMatchesOperation = (
  operation: ManageProductCommercialFeeOperation,
  outcome: ProductCommercialFeeBulkOwnerOutcome,
): boolean => {
  if (outcome.outcome === 'CONFLICT' || outcome.outcome === 'REJECTED' || outcome.outcome === 'INDETERMINATE') {
    return true;
  }
  if (outcome.outcome === 'UNCHANGED') {
    return true;
  }
  if (operation.kind === 'DEFINE_COMMERCIAL_FEE') {
    return outcome.outcome === 'CREATED';
  }
  return Match.value(operation.payload.intent).pipe(
    Match.when('CORRECT_REVISION', () => outcome.outcome === 'CORRECTED'),
    Match.when('RETIRE_CURRENT', () => outcome.outcome === 'RETIRED'),
    Match.when('SCHEDULE_REVISION', () => outcome.outcome === 'SCHEDULED'),
    Match.when('VALUE_ONLY_CURRENT', () => outcome.outcome === 'CHANGED'),
    Match.exhaustive,
  );
};

const verifiedOutcomeFor = <Operation extends ManageProductCommercialFeeOperation>(
  command: ProductCommercialFeeBulkCommand<Operation>,
  outcome: ProductCommercialFeeBulkOwnerOutcome,
  resolvedBy: ProductCommercialFeeBulkTargetOutcome['resolvedBy'],
): ProductCommercialFeeBulkTargetOutcome =>
  ownerOutcomeMatchesOperation(command.operation, outcome)
    ? outcomeFor(command, outcome, resolvedBy)
    : outcomeFor(command, { outcome: 'INDETERMINATE', reasonCode: 'OwnerOutcomeOperationMismatch' }, resolvedBy);

const executeFixedTarget = Effect.fn('ProductCommercialFeeBulkService.executeFixedTarget')(function* executeFixedTarget<
  Operation extends ManageProductCommercialFeeOperation,
>(
  port: ProductCommercialFeeBulkCommandPort<Operation>,
  input: ExecuteProductCommercialFeeBulkInput<Operation>,
  intentsByTarget: ReadonlyMap<string, ProductCommercialFeeBulkTargetIntent<Operation>>,
  target: PricingCommercialFeeProductTargetSnapshot['targets'][number],
) {
  const intent = intentsByTarget.get(target.targetId);
  if (intent === undefined) {
    return yield* reject('BULK_TARGET_SET_MISMATCH', 'A validated fixed target intent is missing');
  }
  const command: ProductCommercialFeeBulkCommand<Operation> = { ...intent, trusted: input.trusted };
  const reconciliation = yield* port.reconcileAuthorizedCommercialFeeAction(command).pipe(
    Effect.match({
      onFailure: (error) => ({ available: false as const, error }),
      onSuccess: (result) => ({ available: true as const, result }),
    }),
  );
  if (!reconciliation.available) {
    return indeterminateFor(command, reconciliation.error, 'OWNER_RECONCILIATION');
  }
  if (reconciliation.result.status === 'RESOLVED') {
    return verifiedOutcomeFor(command, reconciliation.result.outcome, 'OWNER_RECONCILIATION');
  }
  return yield* port.executeAuthorizedCommercialFeeAction(command).pipe(
    Effect.match({
      onFailure: (error) => indeterminateFor(command, error, 'OWNER_COMMAND'),
      onSuccess: (outcome) => verifiedOutcomeFor(command, outcome, 'OWNER_COMMAND'),
    }),
  );
});

/**
 * Product bulk is bounded orchestration only: the snapshot is never re-expanded, and each target
 * gets one reconciliation lookup followed by at most one authorized owner command.
 */
export const makeProductCommercialFeeBulkService = <Operation extends ManageProductCommercialFeeOperation>(
  port: ProductCommercialFeeBulkCommandPort<Operation>,
) =>
  ({
    execute: Effect.fn('ProductCommercialFeeBulkService.execute')(function* execute(
      input: ExecuteProductCommercialFeeBulkInput<Operation>,
    ) {
      const invalid = validateInput(input);
      if (invalid !== undefined) {
        return yield* invalid;
      }
      const intentsByTarget = new Map(input.targetIntents.map((intent) => [intent.identity.targetId, intent]));
      const outcomes = yield* Effect.forEach(
        input.snapshot.targets,
        (target) => executeFixedTarget(port, input, intentsByTarget, target),
        { concurrency: 1 },
      );
      return { outcomes, snapshotId: input.snapshot.snapshotId } satisfies ManageProductCommercialFeesBulkResult;
    }),
  }) satisfies ProductCommercialFeeBulkService<Operation>;

