type DefineProductCommercialFeeOperation = Extract<
  ManageProductCommercialFeeOperation,
  { readonly kind: 'DEFINE_COMMERCIAL_FEE' }
>;
type ReviseProductCommercialFeeOperation = Extract<
  ManageProductCommercialFeeOperation,
  { readonly kind: 'REVISE_COMMERCIAL_FEE' }
>;

const commercialFeePortFailure = <Tag extends string>(
  tag: Tag,
  cause?: unknown,
): ProductCommercialFeeBulkPortFailure & { readonly _tag: Tag; readonly cause: unknown } => ({ _tag: tag, cause });

const feeCanonicalFromDefinition = (definition: {
  readonly feeRef: ProductCommercialFeeBulkCanonicalRefs['feeRef'];
  readonly revision: { readonly revisionId: string };
}) => ({ feeRef: definition.feeRef, revisionId: definition.revision.revisionId });

const latestFeeRevisionId = (schedule: {
  readonly revisions: readonly {
    readonly definition: { readonly revision: { readonly revision: number; readonly revisionId: string } };
  }[];
}): string | undefined => {
  let latest: { readonly revision: number; readonly revisionId: string } | undefined;
  for (const entry of schedule.revisions) {
    if (latest === undefined || entry.definition.revision.revision > latest.revision) {
      latest = entry.definition.revision;
    }
  }
  return latest?.revisionId;
};

const sameFeePeriod = Schema.toEquivalence(PricingCommercialFeeEffectivePeriodSchema);

const feeResultMatchesOperation = (
  operation: ManageProductCommercialFeeOperation,
  target: PriceProductTargetOutcomeIdentity['target'],
  result: Extract<
    CommercialFeeActionResultLookupOutcome,
    { readonly outcome: 'COMMERCIAL_FEE_ACTION_RESULT_FOUND' }
  >['result'],
): boolean => {
  if (operation.kind === 'DEFINE_COMMERCIAL_FEE') {
    return (
      (result.outcome === 'COMMERCIAL_FEE_CREATED' || result.outcome === 'COMMERCIAL_FEE_REUSED') &&
      result.definition.identityKey.target.variantRef.resourceId === target.variantRef.resourceId &&
      result.definition.identityKey.target.variantRef.tenantId === target.variantRef.tenantId &&
      pricingCommercialFeeIdentityKeysEqual(result.definition.identityKey, operation.payload.identityKey) &&
      result.definition.revision.effectiveFrom === operation.payload.effectivePeriod.effectiveFrom &&
      result.definition.revision.configuredAmount.currencyCode === operation.payload.configuredAmount.currencyCode &&
      priceDecimalValuesEqual(
        result.definition.revision.configuredAmount.amount,
        operation.payload.configuredAmount.amount,
      )
    );
  }
  if (result.outcome !== 'COMMERCIAL_FEE_REVISED' && result.outcome !== 'COMMERCIAL_FEE_UNCHANGED') {
    return false;
  }
  if (
    result.schedule.identityKey.target.variantRef.resourceId !== target.variantRef.resourceId ||
    result.schedule.identityKey.target.variantRef.tenantId !== target.variantRef.tenantId ||
    !pricingCommercialFeeIdentityKeysEqual(result.schedule.identityKey, operation.payload.identityKey)
  ) {
    return false;
  }
  const { payload } = operation;
  if (payload.intent === 'RETIRE_CURRENT') {
    return true;
  }
  let intendedPeriod: PricingCommercialFeeEffectivePeriod | undefined;
  if (payload.intent === 'SCHEDULE_REVISION') {
    intendedPeriod = payload.effectivePeriod;
  } else if (payload.intent === 'CORRECT_REVISION') {
    intendedPeriod = payload.targetEffectivePeriod;
  }
  return result.schedule.revisions.some(({ definition, effectivePeriod }) => {
    const amountMatches =
      definition.revision.configuredAmount.currencyCode === payload.configuredAmount.currencyCode &&
      priceDecimalValuesEqual(definition.revision.configuredAmount.amount, payload.configuredAmount.amount);
    if (!amountMatches) {
      return false;
    }
    if (payload.intent === 'VALUE_ONLY_CURRENT') {
      return effectivePeriod.effectiveFrom === payload.effectiveFrom;
    }
    return intendedPeriod !== undefined && sameFeePeriod(effectivePeriod, intendedPeriod);
  });
};

const successfulFeeRevisionOutcome = (
  target: PriceProductTargetOutcomeIdentity['target'],
  operation: ReviseProductCommercialFeeOperation,
  result: Extract<
    ReviseCommercialFeePersistenceOutcome,
    { readonly outcome: 'COMMERCIAL_FEE_REVISED' | 'COMMERCIAL_FEE_UNCHANGED' }
  >,
): ProductCommercialFeeBulkOwnerOutcome => {
  if (!feeResultMatchesOperation(operation, target, result)) {
    return { outcome: 'CONFLICT', reasonCode: 'IDEMPOTENCY_CONFLICT' };
  }
  const revisionId = latestFeeRevisionId(result.schedule);
  const canonical =
    revisionId === undefined ? { feeRef: result.schedule.feeRef } : { feeRef: result.schedule.feeRef, revisionId };
  if (result.outcome === 'COMMERCIAL_FEE_UNCHANGED') {
    return { canonical, outcome: 'UNCHANGED' };
  }
  if (operation.payload.intent === 'CORRECT_REVISION') {
    return { canonical, outcome: 'CORRECTED' };
  }
  if (operation.payload.intent === 'RETIRE_CURRENT') {
    return { canonical, outcome: 'RETIRED' };
  }
  return {
    canonical,
    outcome: operation.payload.intent === 'SCHEDULE_REVISION' ? 'SCHEDULED' : 'CHANGED',
  };
};

const ownerOutcomeFromCommercialFeeResult = (
  command: ProductCommercialFeeBulkCommand<ManageProductCommercialFeeOperation>,
  result: Extract<
    CommercialFeeActionResultLookupOutcome,
    { readonly outcome: 'COMMERCIAL_FEE_ACTION_RESULT_FOUND' }
  >['result'],
): ProductCommercialFeeBulkOwnerOutcome => {
  if (!feeResultMatchesOperation(command.operation, command.identity.target, result)) {
    return { outcome: 'CONFLICT', reasonCode: 'IDEMPOTENCY_CONFLICT' };
  }
  if (result.outcome === 'COMMERCIAL_FEE_CREATED' || result.outcome === 'COMMERCIAL_FEE_REUSED') {
    return {
      canonical: feeCanonicalFromDefinition(result.definition),
      outcome: result.outcome === 'COMMERCIAL_FEE_CREATED' ? 'CREATED' : 'UNCHANGED',
    };
  }
  if (result.outcome === 'COMMERCIAL_FEE_CONFLICT') {
    return { outcome: 'CONFLICT', reasonCode: result.reason };
  }
  if (result.outcome === 'COMMERCIAL_FEE_ACKNOWLEDGEMENT_REQUIRED') {
    return {
      acknowledgementChallenge: result.acknowledgement,
      outcome: 'REJECTED',
      reasonCode: 'COMMERCIAL_FEE_SCHEDULE_ACKNOWLEDGEMENT_REQUIRED',
    };
  }
  if (
    command.operation.kind === 'REVISE_COMMERCIAL_FEE' &&
    (result.outcome === 'COMMERCIAL_FEE_REVISED' || result.outcome === 'COMMERCIAL_FEE_UNCHANGED')
  ) {
    return successfulFeeRevisionOutcome(command.identity.target, command.operation, result);
  }
  return { outcome: 'INDETERMINATE', reasonCode: 'OwnerOutcomeOperationMismatch' };
};

const reconcileCommercialFeeTarget = (
  persistence: TransactionScopedCommercialFeePersistence,
  command: ProductCommercialFeeBulkCommand<ManageProductCommercialFeeOperation>,
  actionInvocationId: string,
) =>
  persistence.lookupResult({ actionInvocationId }).pipe(
    Effect.map((lookup) =>
      lookup.outcome === 'COMMERCIAL_FEE_ACTION_RESULT_FOUND'
        ? ({
            outcome: ownerOutcomeFromCommercialFeeResult(command, lookup.result),
            status: 'RESOLVED' as const,
          } as const)
        : ({ status: 'RETRY_ALLOWED' as const } as const),
    ),
    Effect.mapError((cause) => commercialFeePortFailure('CommercialFeeOwnerResultLookupUnavailable', cause)),
  );

const commercialFeeCommandTrusted = (
  command: ProductCommercialFeeBulkCommand<ManageProductCommercialFeeOperation>,
  actionInvocationId: string,
) => ({
  actingPrincipalId: command.trusted.principalContext.principalId,
  actionInvocationId,
  compositionRevision: command.trusted.compositionRevision,
  legalEntityId: command.trusted.principalContext.legalEntityId,
  requestCorrelationId: command.targetCorrelationRef,
  tenantId: command.trusted.principalContext.tenantId,
  trustedOperationAt: command.trusted.trustedOperationAt,
});

const rejectedCommercialFeeOutcome = (
  reasonCode: string,
  acknowledgementChallenge?: PricingCommercialFeeScheduleAcknowledgement,
): ProductCommercialFeeBulkOwnerOutcome => {
  if (acknowledgementChallenge === undefined) {
    return { outcome: 'REJECTED', reasonCode };
  }
  return { acknowledgementChallenge, outcome: 'REJECTED', reasonCode };
};

const handleDefineConflict = (error: DefineCommercialFeeConflict) =>
  Effect.succeed({ outcome: 'CONFLICT' as const, reasonCode: error.reason });

const handleDefineRejected = (error: DefineCommercialFeeRejected) =>
  Effect.succeed(rejectedCommercialFeeOutcome(error.code));

const handleRevisionAcknowledgement = (error: ReviseCommercialFeeAcknowledgementRequired) =>
  Effect.succeed(
    rejectedCommercialFeeOutcome('COMMERCIAL_FEE_SCHEDULE_ACKNOWLEDGEMENT_REQUIRED', error.acknowledgement),
  );

const handleRevisionConflict = (error: ReviseCommercialFeeConflict) =>
  Effect.succeed({ outcome: 'CONFLICT' as const, reasonCode: error.reason });

const handleRevisionRejected = (error: ReviseCommercialFeeRejected) =>
  Effect.succeed(rejectedCommercialFeeOutcome(error.code));

const executeCommercialFeeDefinition = (execution: ReturnType<typeof applyCommercialFeeDefinition>) =>
  execution.pipe(
    Effect.map((result): ProductCommercialFeeBulkOwnerOutcome => ({
      canonical: feeCanonicalFromDefinition(result.definition),
      outcome: result.outcome === 'COMMERCIAL_FEE_CREATED' ? 'CREATED' : 'UNCHANGED',
    })),
    Effect.catchTags({
      CommercialFeePersistenceUnavailable: () =>
        Effect.fail(commercialFeePortFailure('CommercialFeePersistenceUnavailable')),
      CurrencySupportPersistenceUnavailable: () =>
        Effect.fail(commercialFeePortFailure('CommercialFeeCurrencySupportUnavailable')),
      DefineCommercialFeeConflict: handleDefineConflict,
      DefineCommercialFeeRejected: handleDefineRejected,
      PricingCatalogSelectionUnavailable: () =>
        Effect.fail(commercialFeePortFailure('CommercialFeeCatalogSelectionUnavailable')),
    }),
  );

const executeCommercialFeeRevision = (
  command: ProductCommercialFeeBulkCommand<ManageProductCommercialFeeOperation>,
  operation: ReviseProductCommercialFeeOperation,
  execution: ReturnType<typeof applyCommercialFeeRevision>,
) =>
  execution.pipe(
    Effect.map((result) => successfulFeeRevisionOutcome(command.identity.target, operation, result)),
    Effect.catchTags({
      CommercialFeePersistenceUnavailable: () =>
        Effect.fail(commercialFeePortFailure('CommercialFeePersistenceUnavailable')),
      CurrencySupportPersistenceUnavailable: () =>
        Effect.fail(commercialFeePortFailure('CommercialFeeCurrencySupportUnavailable')),
      PricingCatalogSelectionUnavailable: () =>
        Effect.fail(commercialFeePortFailure('CommercialFeeCatalogSelectionUnavailable')),
      ReviseCommercialFeeAcknowledgementRequired: handleRevisionAcknowledgement,
      ReviseCommercialFeeConflict: handleRevisionConflict,
      ReviseCommercialFeeRejected: handleRevisionRejected,
    }),
  );

export const makeProductCommercialFeeBulkCommandPort = (
  options: ProductCommercialFeeBulkCommandDependencies,
): ProductCommercialFeeBulkCommandPort<ManageProductCommercialFeeOperation> =>
  productCommercialFeeBulkCommandExecution({
    executeAuthorizedCommercialFeeAction: (command) => {
      const actionInvocationId = productCommercialFeeBulkActionInvocationIdFor(
        command.trusted.principalContext.tenantId,
        command.intentId,
      );
      const { operation } = command;
      return operation.kind === 'DEFINE_COMMERCIAL_FEE'
        ? executeCommercialFeeDefinition(
            applyCommercialFeeDefinition(
              operation.payload,
              commercialFeeCommandTrusted(command, actionInvocationId),
              options.defineServices,
            ),
          )
        : executeCommercialFeeRevision(
            command,
            operation,
            applyCommercialFeeRevision(
              operation.payload,
              commercialFeeCommandTrusted(command, actionInvocationId),
              options.reviseServices,
            ),
          );
    },
    reconcileAuthorizedCommercialFeeAction: (command) =>
      reconcileCommercialFeeTarget(
        options.persistence,
        command,
        productCommercialFeeBulkActionInvocationIdFor(command.trusted.principalContext.tenantId, command.intentId),
      ),
  });

export const productCommercialFeeBulkCommandOptionsForScope: ActionServiceFactory<ProductCommercialFeeBulkWriteDependencies> =
  Effect.fn('ProductCommercialFeeBulkService.writeServicesForScope')(
    function* makeProductCommercialFeeBulkActionServices(transaction, scope) {
      const persistence = yield* commercialFeePersistenceForScope(transaction, scope);
      return {
        defineServices: { define: persistence.define },
        persistence,
        reviseServices: { revise: persistence.revise },
      } satisfies ProductCommercialFeeBulkWriteDependencies;
    },
  );

/** The current complete Catalog snapshot and each exact target proof are checked outside BEGIN. */
export const prepareProductCommercialFeeBulk = Effect.fn('ProductCommercialFeeBulkService.prepare')(function* prepare(
  input: ExecuteProductCommercialFeeBulkInput<ManageProductCommercialFeeOperation>,
  context: ActionPrepareContext,
) {
  const invalid = validateInput(input);
  if (invalid !== undefined) {return yield* invalid;}
  if (context.scope.legalEntityId === undefined)
    {return yield* reject('BULK_SCOPE_MISMATCH', 'Commercial Fee Product bulk requires a trusted Selling Legal Entity');}
  const services = yield* pricingActionPreparationForScope(context);
  const snapshot = yield* productCommercialFeeBulkCatalogSnapshotPortFromEnvironment({
    compositionRevision: context.compositionRevision,
    legalEntityId: context.scope.legalEntityId,
    requestCorrelation: context.scope.correlationId,
  });
  if (!(yield* snapshot.validateCurrent(input.snapshot))) {
    return yield* reject(
      'BULK_TARGET_IDENTITY_MISMATCH',
      'Catalog no longer verifies the exact complete Product/Variant snapshot',
    );
  }
  const plans = new Map<
    string,
    (
      options: ProductCommercialFeeBulkWriteDependencies,
    ) => Effect.Effect<ProductCommercialFeeBulkOwnerOutcome, ProductCommercialFeeBulkPortFailure>
  >();
  for (const intent of input.targetIntents) {
    const command = { ...intent, trusted: input.trusted };
    const actionInvocationId = productCommercialFeeBulkActionInvocationIdFor(context.scope.tenantId, intent.intentId);
    const reconciliation = yield* context
      .transaction((transaction) =>
        commercialFeePersistenceForScope(transaction, context.scope).pipe(
          Effect.flatMap((persistence) => reconcileCommercialFeeTarget(persistence, command, actionInvocationId)),
        ),
      )
      .pipe(
        Effect.match({
          onFailure: (cause) => ({
            failure: commercialFeePortFailure('CommercialFeeOwnerResultLookupUnavailable', cause),
          }),
          onSuccess: (result) => ({ result }),
        }),
      );
    if ('failure' in reconciliation) {
      plans.set(intent.intentId, () => Effect.fail(reconciliation.failure));
      continue;
    }
    if (reconciliation.result.status === 'RESOLVED') {
      const { outcome } = reconciliation.result;
      plans.set(intent.intentId, () => Effect.succeed(outcome));
      continue;
    }
    const { operation } = intent;
    const trusted = commercialFeeCommandTrusted(command, actionInvocationId);
    if (operation.kind === 'DEFINE_COMMERCIAL_FEE') {
      const preparation: ReturnType<typeof prepareCommercialFeeDefinition> = yield* prepareCommercialFeeDefinition(
        operation.payload,
        trusted,
        services,
      ).pipe(
        Effect.match({ onFailure: (failure) => Effect.fail(failure), onSuccess: (write) => Effect.succeed(write) }),
      );
      plans.set(intent.intentId, (options) =>
        executeCommercialFeeDefinition(preparation.pipe(Effect.flatMap((write) => write(options.defineServices)))),
      );
    } else {
      const preparation: ReturnType<typeof prepareCommercialFeeRevision> = yield* prepareCommercialFeeRevision(
        operation.payload,
        trusted,
        services,
      ).pipe(
        Effect.match({ onFailure: (failure) => Effect.fail(failure), onSuccess: (write) => Effect.succeed(write) }),
      );
      plans.set(intent.intentId, (options) =>
        executeCommercialFeeRevision(
          command,
          operation,
          preparation.pipe(Effect.flatMap((write) => write(options.reviseServices))),
        ),
      );
    }
  }
  return (
    options: ProductCommercialFeeBulkWriteDependencies,
  ): Effect.Effect<ManageProductCommercialFeesBulkResult, ProductCommercialFeeBulkRejected> => 
    makeProductCommercialFeeBulkService(
      productCommercialFeeBulkCommandExecution({
        executeAuthorizedCommercialFeeAction: (command) => {
          const plan = plans.get(command.intentId);
          return plan === undefined
            ? Effect.fail(commercialFeePortFailure('CommercialFeePreparedIntentMissing'))
            : plan(options);
        },
        reconcileAuthorizedCommercialFeeAction: (command) =>
          reconcileCommercialFeeTarget(
            options.persistence,
            command,
            productCommercialFeeBulkActionInvocationIdFor(command.trusted.principalContext.tenantId, command.intentId),
          ),
      }),
    ).execute(input)
  ;
});
